import { useEffect, useMemo, useState } from 'react'
import { api } from '../services/api.js'
import { useAuth } from '../auth/useAuth.js'
import { DataTable, Field, Message, PageIntro, Panel, Pill } from '../components/ui.jsx'

export function ResultsPage() {
  const { user } = useAuth()
  const isStaff = useMemo(() => user?.role === 'admin' || user?.role === 'teacher', [user?.role])
  const [error, setError] = useState('')
  const [results, setResults] = useState([])
  const [studentId, setStudentId] = useState('')
  const [form, setForm] = useState({ student_id: '', exam_id: '', subject: '', marks: '', total_marks: '' })

  async function loadForStudent(id) {
    setError('')
    try {
      const res = await api.get(`/results/${id}`)
      setResults(res.data.results || [])
    } catch (e) {
      setResults([])
      setError(e?.response?.data?.error || 'Failed to load results')
    }
  }

  useEffect(() => {
    if (isStaff) return
    ;(async () => {
      try {
        const me = await api.get('/students/me')
        await loadForStudent(me.data.student.id)
      } catch (e) {
        setError(e?.response?.data?.error || 'Failed to load results')
      }
    })()
  }, [isStaff])

  async function search(event) {
    event.preventDefault()
    if (!studentId) return
    await loadForStudent(Number(studentId))
  }

  async function addResult(event) {
    event.preventDefault()
    setError('')
    try {
      await api.post('/results', {
        student_id: Number(form.student_id),
        exam_id: Number(form.exam_id),
        subject: form.subject,
        marks: Number(form.marks),
        total_marks: Number(form.total_marks),
      })
      setForm({ student_id: '', exam_id: '', subject: '', marks: '', total_marks: '' })
      if (studentId) await loadForStudent(Number(studentId))
    } catch (e) {
      setError(e?.response?.data?.error || 'Failed to create result')
    }
  }

  return (
    <div className="space-y-6">
      <PageIntro
        eyebrow="Results"
        title={isStaff ? 'Capture marks with less busywork' : 'View your academic results'}
        description={
          isStaff
            ? 'Search results by student, enter fresh marks, and keep exam performance up to date.'
            : 'A simplified result view highlights each exam and subject without clutter.'
        }
      />

      {error ? <Message>{error}</Message> : null}

      {isStaff ? (
        <div className="content-grid">
          <Panel title="View results" subtitle="Load result history for a specific student.">
            <form onSubmit={search} className="grid gap-4 md:grid-cols-[minmax(0,1fr)_160px]">
              <Field label="Student ID" value={studentId} onChange={setStudentId} placeholder="Search by student id" />
              <div className="flex items-end">
                <button className="app-button w-full">Search</button>
              </div>
            </form>
          </Panel>

          <Panel title="Enter marks" subtitle="Record a new subject result for an exam and student.">
            <form onSubmit={addResult} className="grid grid-cols-1 gap-4 md:grid-cols-2">
              <Field label="Student ID" value={form.student_id} onChange={(value) => setForm((current) => ({ ...current, student_id: value }))} />
              <Field label="Exam ID" value={form.exam_id} onChange={(value) => setForm((current) => ({ ...current, exam_id: value }))} />
              <Field label="Subject" value={form.subject} onChange={(value) => setForm((current) => ({ ...current, subject: value }))} />
              <Field label="Marks" value={form.marks} onChange={(value) => setForm((current) => ({ ...current, marks: value }))} />
              <Field label="Total Marks" value={form.total_marks} onChange={(value) => setForm((current) => ({ ...current, total_marks: value }))} />
              <div className="md:col-span-2">
                <button className="app-button">Save result</button>
              </div>
            </form>
          </Panel>
        </div>
      ) : null}

      <Panel title="Result table" subtitle={isStaff ? 'Loaded results for the selected student.' : 'Your current academic record.'}>
        <DataTable
          columns={['Exam', 'Subject', 'Marks', 'Total', 'Performance']}
          rows={results}
          empty="No results yet"
          renderRow={(result) => {
            const percent = result.total_marks ? Math.round((Number(result.marks) / Number(result.total_marks)) * 100) : 0
            return (
              <tr key={result.id}>
                <td className="font-semibold text-slate-900">{result.exam_name || result.exam_id}</td>
                <td>{result.subject}</td>
                <td>{result.marks}</td>
                <td>{result.total_marks}</td>
                <td>
                  <Pill tone={percent >= 75 ? 'emerald' : percent >= 50 ? 'amber' : 'rose'}>
                    {percent}%
                  </Pill>
                </td>
              </tr>
            )
          }}
        />
      </Panel>
    </div>
  )
}
